ALTER TABLE "appointments" ADD COLUMN "patient_cancelled_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "appointments" ADD COLUMN "patient_cancellation_late" boolean;--> statement-breakpoint
ALTER TABLE "appointments" ADD CONSTRAINT "appointment_patient_cancellation" CHECK (("appointments"."patient_cancelled_at" is null and "appointments"."patient_cancellation_late" is null) or ("appointments"."patient_cancelled_at" is not null and "appointments"."patient_cancellation_late" is not null and "appointments"."status" = 'cancelled' and "appointments"."patient_user_id" is not null and "appointments"."cancelled_by_staff_id" is null and "appointments"."patient_cancelled_at" < "appointments"."starts_at" and "appointments"."patient_cancellation_late" = ("appointments"."starts_at" - "appointments"."patient_cancelled_at" < interval '2 hours')));